.v7-banner-clean {
    background-color: #ffffff;
    border: 2px solid #0e535e; /* Venture7 Teal Border */
    padding: 30px;
    border-radius: 6px;
    font-family: sans-serif;
    text-align: center;
    margin: 40px 0;
  }
  .v7-banner-clean h3 {
    color: #0e535e; /* Venture7 Teal Text */
    margin: 0 0 10px 0;
    font-size: 22px;
    font-weight: 700;
  }
  .v7-banner-clean p {
    color: #475569;
    margin: 0 0 20px 0;
    font-size: 16px;
  }
  .v7-btn-clean {
    background-color: #0e535e; /* Venture7 Teal Button */
    color: #fcc82d !important; /* Venture7 Gold Text */
    text-decoration: none;
    font-weight: bold;
    padding: 12px 28px;
    border-radius: 50px;
    display: inline-block;
    transition: background-color 0.3s;
  }
  .v7-btn-clean:hover {
    background-color: #083b42; /* Darker Teal on hover */
    color: #ffffff !important;
  }

